import json, sys
steps = []
steps.append({"note": "Create the trigger function that copies customer_id into the new bigint column on every insert/update.",
  "sql": """CREATE OR REPLACE FUNCTION public.orders_customer_id_sync() RETURNS trigger LANGUAGE plpgsql AS $f$
BEGIN
  NEW.customer_id_new := NEW.customer_id;
  RETURN NEW;
END
$f$;"""})
steps.append({"note": "In one short transaction (lock retried with a 300ms lock_timeout so app queries never queue for long): add nullable bigint column customer_id_new (metadata-only, no rewrite), a NOT VALID check that it is not null (enforced for new rows only), and the sync trigger. From here on every new order fills both columns.",
  "sql": """DO $$
BEGIN
  FOR i IN 1..100 LOOP
    BEGIN
      PERFORM set_config('lock_timeout', '300ms', true);
      LOCK TABLE public.orders IN ACCESS EXCLUSIVE MODE;
      ALTER TABLE public.orders ADD COLUMN customer_id_new bigint;
      ALTER TABLE public.orders ADD CONSTRAINT orders_customer_id_new_chk CHECK (customer_id_new IS NOT NULL) NOT VALID;
      CREATE TRIGGER orders_customer_id_sync BEFORE INSERT OR UPDATE ON public.orders
        FOR EACH ROW EXECUTE FUNCTION public.orders_customer_id_sync();
      RETURN;
    EXCEPTION WHEN lock_not_available THEN
      PERFORM pg_sleep(0.5);
    END;
  END LOOP;
  RAISE EXCEPTION 'could not lock orders to add customer_id_new';
END
$$;"""})
B = 50_000; G = 1_000_000; END = 10_000_000
for g in range(0, END, G):
    stmts = []
    for lo in range(g, g + G, B):
        hi = lo + B
        if lo == 0:
            cond = f"id < {hi}"
        elif hi >= END:
            cond = f"id >= {lo}"          # open-ended: covers every row inserted before the trigger existed
        else:
            cond = f"id >= {lo} AND id < {hi}"
        stmts.append(f"UPDATE public.orders SET customer_id_new = customer_id WHERE {cond} AND customer_id_new IS NULL;")
        stmts.append("SELECT pg_sleep(0.1);")
    last = "id >= %d (open-ended, up to the newest row)" % g if g + G >= END else "id < %d" % (g + G)
    steps.append({"note": f"Backfill customer_id_new from customer_id for ids from {g} to {last}, in 50k-row autocommitted batches with short pauses. Only rows the app never updates are touched; no table lock is taken.",
                  "sql": "SET statement_timeout = 0;\n" + "\n".join(stmts)})
    steps.append({"note": "VACUUM so the space of the old row versions is reused by the next batches (keeps the table from doubling in size). Does not block reads or writes.",
                  "sql": "VACUUM public.orders;"})
steps.append({"note": "Verify: no row may have customer_id_new different from customer_id. Fails the plan (before anything is swapped) if any does.",
  "sql": """SET statement_timeout = 0;
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM public.orders WHERE customer_id_new IS DISTINCT FROM customer_id) THEN
    RAISE EXCEPTION 'customer_id_new does not match customer_id on some rows';
  END IF;
END
$$;"""})
steps.append({"note": "Validate the not-null check over all rows. Takes only a SHARE UPDATE EXCLUSIVE lock, so reads and writes continue.",
  "sql": "SET statement_timeout = 0;\nALTER TABLE public.orders VALIDATE CONSTRAINT orders_customer_id_new_chk;"})
steps.append({"note": "Collect planner statistics for the new column (they stay with it after the rename), so the /customer query keeps its plan.",
  "sql": "SET statement_timeout = 0;\nANALYZE public.orders;"})
steps.append({"note": "Swap in one short transaction (lock retried with a 300ms lock_timeout): SET NOT NULL on customer_id_new (instant, proven by the validated check), drop the check and the trigger, drop the old integer column (metadata-only), rename customer_id_new to customer_id. The app's SQL is unchanged and sees customer_id as bigint from the next query on.",
  "sql": """DO $$
BEGIN
  FOR i IN 1..100 LOOP
    BEGIN
      PERFORM set_config('lock_timeout', '300ms', true);
      LOCK TABLE public.orders IN ACCESS EXCLUSIVE MODE;
      ALTER TABLE public.orders ALTER COLUMN customer_id_new SET NOT NULL;
      ALTER TABLE public.orders DROP CONSTRAINT orders_customer_id_new_chk;
      DROP TRIGGER orders_customer_id_sync ON public.orders;
      ALTER TABLE public.orders DROP COLUMN customer_id;
      ALTER TABLE public.orders RENAME COLUMN customer_id_new TO customer_id;
      RETURN;
    EXCEPTION WHEN lock_not_available THEN
      PERFORM pg_sleep(0.5);
    END;
  END LOOP;
  RAISE EXCEPTION 'could not lock orders to swap customer_id';
END
$$;"""})
steps.append({"note": "Clean up the trigger function and check the result: orders.customer_id is bigint NOT NULL.",
  "sql": """DROP FUNCTION public.orders_customer_id_sync();
DO $$
BEGIN
  IF NOT EXISTS (SELECT 1 FROM information_schema.columns
                 WHERE table_schema = 'public' AND table_name = 'orders' AND column_name = 'customer_id'
                   AND data_type = 'bigint' AND is_nullable = 'NO') THEN
    RAISE EXCEPTION 'orders.customer_id is not bigint NOT NULL';
  END IF;
END
$$;"""})
json.dump({"task": "customer-bigint", "steps": steps}, open(sys.argv[1], "w"), indent=2)
print(len(steps))
EOF
